package gomplate

import (
	"fmt"
	"os"
	"time"

	"gopkg.in/yaml.v3"
)

type DatasourceConfig struct {
	URL    string              `yaml:"url"`
	Header map[string][]string `yaml:"header"`
}

func (d *DatasourceConfig) UnmarshalYAML(node *yaml.Node) error {
	if node.Kind == yaml.ScalarNode {
		d.URL = node.Value
		return nil
	}

	type raw DatasourceConfig
	var tmp raw
	if err := node.Decode(&tmp); err != nil {
		return err
	}
	*d = DatasourceConfig(tmp)
	return nil
}

type PluginConfig struct {
	Cmd     string        `yaml:"cmd"`
	Args    []string      `yaml:"args"`
	Pipe    bool          `yaml:"pipe"`
	Timeout time.Duration `yaml:"timeout"`
}

func (p *PluginConfig) UnmarshalYAML(node *yaml.Node) error {
	if node.Kind == yaml.ScalarNode {
		p.Cmd = node.Value
		return nil
	}

	type raw PluginConfig
	var tmp raw
	if err := node.Decode(&tmp); err != nil {
		return err
	}
	*p = PluginConfig(tmp)
	return nil
}

type FileConfig struct {
	Chmod             string                      `yaml:"chmod"`
	Context           map[string]DatasourceConfig `yaml:"context"`
	Datasources       map[string]DatasourceConfig `yaml:"datasources"`
	Excludes          []string                    `yaml:"excludes"`
	ExcludeProcessing []string                    `yaml:"excludeProcessing"`
	ExecPipe          bool                        `yaml:"execPipe"`
	Experimental      bool                        `yaml:"experimental"`
	In                string                      `yaml:"in"`
	InputDir          string                      `yaml:"inputDir"`
	InputFiles        []string                    `yaml:"inputFiles"`
	LeftDelim         string                      `yaml:"leftDelim"`
	MissingKey        string                      `yaml:"missingKey"`
	OutputDir         string                      `yaml:"outputDir"`
	OutputFiles       []string                    `yaml:"outputFiles"`
	OutputMap         string                      `yaml:"outputMap"`
	Plugins           map[string]PluginConfig     `yaml:"plugins"`
	PluginTimeout     time.Duration               `yaml:"pluginTimeout"`
	RightDelim        string                      `yaml:"rightDelim"`
	Templates         map[string]DatasourceConfig `yaml:"templates"`
}

func loadFileConfig(path string) (FileConfig, error) {
	var cfg FileConfig
	data, err := os.ReadFile(path)
	if err != nil {
		return cfg, fmt.Errorf("load config %s: %w", path, err)
	}
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return cfg, fmt.Errorf("parse config %s: %w", path, err)
	}
	return cfg, nil
}

