	return errors.As(err, &target)
}

func usageErrorf(format string, args ...any) error {
	return &usageError{err: fmt.Errorf(format, args...)}
}

func NewApp(logger *slog.Logger) *App {
	return &App{logger: logger}
}

func (a *App) Command() *cobra.Command {
	cmd := &cobra.Command{
		Use:           "gomplate",
		Short:         "Process text files with Go templates",
		Version:       "0.0.0",
		SilenceErrors: true,
		SilenceUsage:  true,
		RunE: func(cmd *cobra.Command, _ []string) error {
			cfg, err := a.resolveConfig(cmd)
			if err != nil {
				return err
			}
			return a.run(cfg)
		},
	}

	cmd.SetVersionTemplate("{{.Name}} version {{.Version}}\n")
	cmd.CompletionOptions.DisableDefaultCmd = true

	flags := cmd.Flags()
	flags.SortFlags = false

	flags.StringArrayVarP(&a.cli.Datasources, "datasource", "d", nil, "datasource in alias=URL form. Specify multiple times to add multiple sources.")
	flags.StringArrayVarP(&a.cli.DatasourceHeaders, "datasource-header", "H", nil, "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
	flags.StringArrayVarP(&a.cli.Contexts, "context", "c", nil, "pre-load a datasource into the context, in alias=URL form. Use the special alias `.` to set the root context.")
