	flags.StringVar(&a.cli.InputDir, "input-dir", "", "directory which is examined recursively for templates (alternative to --file and --in)")
	flags.StringArrayVar(&a.cli.Excludes, "exclude", nil, "glob of files to not parse")
	flags.StringArrayVar(&a.cli.ExcludeProcessing, "exclude-processing", nil, "glob of files to be copied without parsing")
	flags.StringArrayVar(&a.cli.Includes, "include", nil, "glob of files to parse")
	flags.StringArrayVarP(&a.cli.Outs, "out", "o", []string{"-"}, "output file name. Omit to use standard output.")
	flags.StringArrayVarP(&a.cli.Templates, "template", "t", nil, "Additional template file(s)")
	flags.StringVar(&a.cli.OutputDir, "output-dir", ".", "directory to store the processed templates. Only used for --input-dir")
	flags.StringVar(&a.cli.OutputMap, "output-map", "", "Template string to map the input file to an output path")
	flags.StringVar(&a.cli.Chmod, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
	flags.BoolVar(&a.cli.ExecPipe, "exec-pipe", false, "pipe the output to the post-run exec command")
	flags.StringVar(&a.cli.LeftDelim, "left-delim", "{{", "override the default left-delimiter [$GOMPLATE_LEFT_DELIM]")
	flags.StringVar(&a.cli.RightDelim, "right-delim", "}}", "override the default right-delimiter [$GOMPLATE_RIGHT_DELIM]")
	flags.StringVar(&a.cli.MissingKey, "missing-key", "error", `Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>`)
