func defaultRuntimeConfig() *RuntimeConfig {
	return &RuntimeConfig{
		Context:       map[string]DatasourceConfig{},
		Datasources:   map[string]DatasourceConfig{},
		LeftDelim:     "{{",
		MissingKey:    "error",
		OutputDir:     ".",
		PluginTimeout: 5 * time.Second,
		Plugins:       map[string]PluginConfig{},
		RightDelim:    "}}",
		Templates:     map[string]DatasourceConfig{},
	}
}

func (a *App) resolveConfig(cmd *cobra.Command) (*RuntimeConfig, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return nil, err
	}

	cfg := defaultRuntimeConfig()

	if value, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok {
		cfg.LeftDelim = value
	}
	if value, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
		cfg.RightDelim = value
	}
	if value, ok := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); ok {
		if parsed, err := strconv.ParseBool(value); err == nil {
			cfg.Experimental = parsed
		}
	}

	configPath, configExplicit, err := resolveConfigPath(cmd, a.cli.Config)
	if err != nil {
		return nil, err
	}
	if configPath != "" {
		fileCfg, loadErr := loadConfigFile(configPath)
		if loadErr != nil {
			if !configExplicit && errors.Is(loadErr, os.ErrNotExist) {
				goto applyCLI
			}
			return nil, loadErr
		}
		applyFileConfig(cfg, fileCfg)
	}

applyCLI:
	if cmd.Flags().Changed("datasource") {
		for _, raw := range a.cli.Datasources {
			alias, ds, err := parseDatasourceArg(raw, cwd)
			if err != nil {
				return nil, err
			}
			cfg.Datasources[alias] = mergeDatasource(cfg.Datasources[alias], ds)
		}
	}

	if cmd.Flags().Changed("datasource-header") {
		for _, raw := range a.cli.DatasourceHeaders {
			alias, name, value, err := parseHeaderArg(raw)
			if err != nil {
				return nil, err
			}
			ds := cfg.Datasources[alias]
			if ds.Header == nil {
				ds.Header = map[string][]string{}
			}
			ds.Header[name] = append(ds.Header[name], value)
			cfg.Datasources[alias] = ds
		}
	}

	if cmd.Flags().Changed("context") {
		for _, raw := range a.cli.Contexts {
			alias, ds, err := parseDatasourceArg(raw, cwd)
			if err != nil {
				return nil, err
			}
			cfg.Context[alias] = mergeDatasource(cfg.Context[alias], ds)
		}
	}

	if cmd.Flags().Changed("plugin") {
		for _, raw := range a.cli.Plugins {
			name, plugin, err := parsePluginArg(raw, cfg.PluginTimeout)
			if err != nil {
				return nil, err
			}
			cfg.Plugins[name] = plugin
		}
	}

	if cmd.Flags().Changed("template") {
		for _, raw := range a.cli.Templates {
			alias, ds, err := parseTemplateArg(raw)
			if err != nil {
				return nil, err
			}
			cfg.Templates[alias] = mergeDatasource(cfg.Templates[alias], ds)
		}
	}

	if cmd.Flags().Changed("file") {
		cfg.InputFiles = append([]string(nil), a.cli.Files...)
	}
	if cmd.Flags().Changed("out") {
		cfg.OutputFiles = append([]string(nil), a.cli.Outs...)
	}
	if cmd.Flags().Changed("in") {
		in := a.cli.In
		cfg.In = &in
	}
	if cmd.Flags().Changed("input-dir") {
		cfg.InputDir = a.cli.InputDir
	}
	if cmd.Flags().Changed("exclude") {
		cfg.Excludes = append([]string(nil), a.cli.Excludes...)
	}
	if cmd.Flags().Changed("exclude-processing") {
		cfg.ExcludeProcessing = append([]string(nil), a.cli.ExcludeProcessing...)
	}
	if cmd.Flags().Changed("include") {
		cfg.Includes = append([]string(nil), a.cli.Includes...)
	}
	if cmd.Flags().Changed("output-dir") {
		cfg.OutputDir = a.cli.OutputDir
	}
	if cmd.Flags().Changed("output-map") {
		cfg.OutputMap = a.cli.OutputMap
	}
	if cmd.Flags().Changed("chmod") {
		cfg.Chmod = a.cli.Chmod
	}
	if cmd.Flags().Changed("exec-pipe") {
		cfg.ExecPipe = a.cli.ExecPipe
	}
	if cmd.Flags().Changed("left-delim") {
		cfg.LeftDelim = a.cli.LeftDelim
	}
	if cmd.Flags().Changed("right-delim") {
		cfg.RightDelim = a.cli.RightDelim
	}
	if cmd.Flags().Changed("missing-key") {
		cfg.MissingKey = a.cli.MissingKey
	}
	if cmd.Flags().Changed("experimental") {
		cfg.Experimental = a.cli.Experimental
	}
	if cmd.Flags().Changed("verbose") {
		cfg.Verbose = a.cli.Verbose
	}

	if err := validateRuntimeConfig(cfg); err != nil {
		return nil, err
	}

	return cfg, nil
}

func resolveConfigPath(cmd *cobra.Command, cliValue string) (string, bool, error) {
	if cmd.Flags().Changed("config") {
		return cliValue, true, nil
	}
	if value, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
		return value, value != "", nil
	}
	return ".gomplate.yaml", false, nil
}

func applyFileConfig(dst *RuntimeConfig, src FileConfig) {
	if src.Chmod != "" {
		dst.Chmod = src.Chmod
	}
	mergeDatasources(dst.Context, src.Context)
	mergeDatasources(dst.Datasources, src.Datasources)
	if len(src.Excludes) > 0 {
		dst.Excludes = append([]string(nil), src.Excludes...)
	}
	if len(src.ExcludeProcessing) > 0 {
		dst.ExcludeProcessing = append([]string(nil), src.ExcludeProcessing...)
	}
	if src.ExecPipe {
		dst.ExecPipe = true
	}
	if src.Experimental {
		dst.Experimental = true
	}
	if src.In != "" {
		value := src.In
		dst.In = &value
	}
	if src.InputDir != "" {
		dst.InputDir = src.InputDir
	}
	if len(src.InputFiles) > 0 {
		dst.InputFiles = append([]string(nil), src.InputFiles...)
	}
	if src.LeftDelim != "" {
		dst.LeftDelim = src.LeftDelim
	}
	if src.MissingKey != "" {
		dst.MissingKey = src.MissingKey
	}
	if src.OutputDir != "" {
		dst.OutputDir = src.OutputDir
	}
	if len(src.OutputFiles) > 0 {
		dst.OutputFiles = append([]string(nil), src.OutputFiles...)
	}
	if src.OutputMap != "" {
		dst.OutputMap = src.OutputMap
	}
	for name, plugin := range src.Plugins {
		dst.Plugins[name] = plugin
	}
	if src.PluginTimeout > 0 {
		dst.PluginTimeout = src.PluginTimeout
	}
	if src.RightDelim != "" {
		dst.RightDelim = src.RightDelim
	}
	mergeDatasources(dst.Templates, src.Templates)
}

func validateRuntimeConfig(cfg *RuntimeConfig) error {
	switch cfg.MissingKey {
	case "error", "default", "invalid", "zero":
	default:
		return fmt.Errorf("failed to validate config: unsupported missingKey %q", cfg.MissingKey)
	}

	if cfg.PluginTimeout <= 0 {
		cfg.PluginTimeout = 5 * time.Second
	}

	if cfg.In != nil {
		if cfg.InputDir != "" {
			return fmt.Errorf("failed to validate config: inputDir may not be used with in")
		}
		if len(cfg.OutputFiles) == 0 {
			cfg.OutputFiles = []string{"-"}
		}
		return nil
	}

	if cfg.InputDir != "" {
		if len(cfg.InputFiles) > 0 {
			return fmt.Errorf("failed to validate config: inputFiles may not be used with inputDir")
		}
		if len(cfg.OutputFiles) > 0 {
			return fmt.Errorf("failed to validate config: outputFiles may not be used with inputDir")
		}
		if cfg.OutputDir == "" {
			cfg.OutputDir = "."
		}
		return nil
	}

	if len(cfg.InputFiles) == 0 {
		cfg.InputFiles = []string{"-"}
	}
	if len(cfg.OutputFiles) == 0 {
		cfg.OutputFiles = []string{"-"}
	}
	if len(cfg.InputFiles) != len(cfg.OutputFiles) {
		return fmt.Errorf("failed to validate config: must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options\n---\n%s", len(cfg.OutputFiles), len(cfg.InputFiles), cfg.debugString())
	}
	return nil
}

func (cfg *RuntimeConfig) debugString() string {
	var builder strings.Builder
	if len(cfg.InputFiles) > 0 {
		fmt.Fprintf(&builder, "inputFiles: [%s]\n", strings.Join(cfg.InputFiles, ", "))
	}
	if len(cfg.OutputFiles) > 0 {
		fmt.Fprintf(&builder, "outputFiles: [%s]\n", strings.Join(cfg.OutputFiles, ", "))
	}
	fmt.Fprintf(&builder, "leftDelim: '%s'\n", cfg.LeftDelim)
	fmt.Fprintf(&builder, "rightDelim: '%s'\n", cfg.RightDelim)
	fmt.Fprintf(&builder, "missingKey: %s\n", cfg.MissingKey)
	fmt.Fprintf(&builder, "pluginTimeout: %s\n", cfg.PluginTimeout)
	return builder.String()
}

func parseDatasourceArg(raw, cwd string) (string, DatasourceConfig, error) {
	alias, target, err := parseAliasedPathArg(raw, cwd, true)
	if err != nil {
		return "", DatasourceConfig{}, err
	}
	return alias, DatasourceConfig{URL: target}, nil
}

func parseTemplateArg(raw string) (string, DatasourceConfig, error) {
	if alias, target, ok := splitAssignment(raw); ok {
		if alias == "" || target == "" {
			return "", DatasourceConfig{}, usageErrorf("invalid argument (%s)", raw)
		}
		return alias, DatasourceConfig{URL: target}, nil
	}
	return raw, DatasourceConfig{URL: raw}, nil
}

func parsePluginArg(raw string, timeout time.Duration) (string, PluginConfig, error) {
	name, path, ok := splitAssignment(raw)
	if !ok || name == "" || path == "" {
		return "", PluginConfig{}, usageErrorf("invalid argument (%s)", raw)
	}
	return name, PluginConfig{Cmd: path, Timeout: timeout}, nil
}

func parseHeaderArg(raw string) (string, string, string, error) {
	alias, value, ok := splitAssignment(raw)
	if !ok || alias == "" {
		return "", "", "", usageErrorf("invalid argument (%s)", raw)
	}
	parts := strings.SplitN(value, ":", 2)
	if len(parts) != 2 {
		return "", "", "", usageErrorf("invalid argument (%s)", raw)
	}
	name := strings.TrimSpace(parts[0])
	headerValue := strings.TrimSpace(parts[1])
	if name == "" {
		return "", "", "", usageErrorf("invalid argument (%s)", raw)
	}
	return alias, name, headerValue, nil
}

func parseAliasedPathArg(raw, cwd string, inferAlias bool) (string, string, error) {
	if alias, value, ok := splitAssignment(raw); ok {
		if alias == "" || value == "" {
			return "", "", usageErrorf("invalid argument (%s)", raw)
		}
		return alias, value, nil
	}
	if !inferAlias {
		return "", "", usageErrorf("invalid argument (%s)", raw)
	}

	if looksLikeURL(raw) || filepath.IsAbs(raw) {
		return "", "", usageErrorf("invalid argument (%s): must provide an alias with files not in working directory", raw)
	}

	clean := filepath.Clean(raw)
	if filepath.Dir(clean) != "." {
		return "", "", usageErrorf("invalid argument (%s): must provide an alias with files not in working directory", raw)
	}

	base := filepath.Base(clean)
	ext := filepath.Ext(base)
	alias := strings.TrimSuffix(base, ext)
	if alias == "" {
		return "", "", usageErrorf("invalid argument (%s)", raw)
	}
	return alias, raw, nil
}

func mergeDatasource(dst, src DatasourceConfig) DatasourceConfig {
	if src.URL != "" {
		dst.URL = src.URL
	}
	if len(src.Header) > 0 {
		if dst.Header == nil {
			dst.Header = map[string][]string{}
		}
		for name, values := range src.Header {
			dst.Header[name] = append([]string(nil), values...)
		}
	}
	return dst
}

func mergeDatasources(dst map[string]DatasourceConfig, src map[string]DatasourceConfig) {
	for alias, ds := range src {
		dst[alias] = mergeDatasource(dst[alias], ds)
	}
}

func splitAssignment(raw string) (string, string, bool) {
	index := strings.Index(raw, "=")
	if index < 0 {
		return "", "", false
	}
	return raw[:index], raw[index+1:], true
}

func looksLikeURL(raw string) bool {
	if strings.HasPrefix(raw, "file://") || strings.HasPrefix(raw, "env:") || strings.HasPrefix(raw, "stdin:") {
		return true
	}
	if strings.HasPrefix(raw, "http://") || strings.HasPrefix(raw, "https://") {
		return true
	}
	return false
}

func (a *App) readStdin() ([]byte, error) {
	a.stdinOnce.Do(func() {
		a.stdinData, a.stdinErr = io.ReadAll(os.Stdin)
	})
	return a.stdinData, a.stdinErr
}

