package gomplate

import (
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"text/template"
)

type renderer struct {
	cfg *RuntimeConfig
	ds  *datasourceManager
}

type nopWriteCloser struct {
	io.Writer
}

func (nopWriteCloser) Close() error {
	return nil
}

func (a *App) run(cfg *RuntimeConfig) error {
	ds := newDatasourceManager(cfg, a.readStdin)
	root, err := ds.loadContext(cfg.Context)
	if err != nil {
		return err
	}

	renderer := &renderer{cfg: cfg, ds: ds}

	switch {
	case cfg.InputDir != "":
		return renderer.renderDir(cfg.InputDir, root)
	case cfg.In != nil:
		return renderer.renderInline(*cfg.In, cfg.OutputFiles, root)
	default:
		return renderer.renderFiles(cfg.InputFiles, cfg.OutputFiles, root)
	}
}

func (r *renderer) renderInline(input string, outputs []string, root any) error {
	if len(outputs) == 0 {
		outputs = []string{"-"}
	}
	body := []byte(input)
	for _, output := range outputs {
		if err := r.renderSingle("<arg>", body, output, root, 0o644, 0o755); err != nil {
			return err
		}
	}
	return nil
}

func (r *renderer) renderFiles(inputs, outputs []string, root any) error {
	for index, input := range inputs {
		body, err := r.readInput(input)
		if err != nil {
			return err
		}

		output := "-"
		if index < len(outputs) {
			output = outputs[index]
		}

		mode := fs.FileMode(0o644)
		dirMode := fs.FileMode(0o755)
		if input != "-" {
			if info, err := os.Stat(input); err == nil {
				mode = info.Mode().Perm()
			}
			if info, err := os.Stat(filepath.Dir(input)); err == nil {
				dirMode = info.Mode().Perm()
			}
		}

		if err := r.renderSingle(inputName(input), body, output, root, mode, dirMode); err != nil {
			return err
		}
	}
	return nil
}

func (r *renderer) renderDir(inputDir string, root any) error {
	return filepath.WalkDir(inputDir, func(filePath string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			return nil
		}

		rel, err := filepath.Rel(inputDir, filePath)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)

		skip, copyOnly, err := shouldSkipFile(inputDir, rel, r.cfg)
		if err != nil || skip {
			return err
		}

		outputPath, err := r.outputPathFor(rel, root)
		if err != nil {
			return err
		}

		info, err := entry.Info()
		if err != nil {
			return err
		}
		mode := info.Mode().Perm()
		if r.cfg.Chmod != "" {
			mode, err = parseFileMode(r.cfg.Chmod)
			if err != nil {
				return err
			}
		}

		dirMode := fs.FileMode(0o755)
		if dirInfo, err := os.Stat(filepath.Dir(filePath)); err == nil {
			dirMode = dirInfo.Mode().Perm()
		}

		if copyOnly {
			return copyFile(filePath, outputPath, mode, dirMode)
		}

		body, err := os.ReadFile(filePath)
		if err != nil {
			return err
		}
		return r.renderSingle(rel, body, outputPath, root, mode, dirMode)
	})
}

func (r *renderer) renderSingle(name string, body []byte, output string, root any, mode, dirMode fs.FileMode) error {
	tmpl, err := r.buildTemplateSet(name)
	if err != nil {
		return err
	}
	if _, err := tmpl.Parse(string(body)); err != nil {
		return fmt.Errorf("renderTemplate: parse template %s: %w", name, err)
	}

	if r.cfg.Chmod != "" {
		mode, err = parseFileMode(r.cfg.Chmod)
		if err != nil {
			return err
		}
	}

	writer, err := openOutput(output, mode, dirMode)
	if err != nil {
		return err
	}
	defer writer.Close()

	if err := tmpl.ExecuteTemplate(writer, name, root); err != nil {
		return fmt.Errorf("renderTemplate: failed to render template %s: %w", name, err)
	}
	return nil
}

func (r *renderer) buildTemplateSet(name string) (*template.Template, error) {
	tmpl := template.New(name)
	tmpl = tmpl.Delims(r.cfg.LeftDelim, r.cfg.RightDelim)
	tmpl = tmpl.Option("missingkey=" + normalizeMissingKey(r.cfg.MissingKey))
	tmpl = tmpl.Funcs(buildFuncMap(r.ds, r.cfg))

	aliases := make([]string, 0, len(r.cfg.Templates))
	for alias := range r.cfg.Templates {
		aliases = append(aliases, alias)
	}
	sort.Strings(aliases)

	for _, alias := range aliases {
		if err := r.addTemplateRef(tmpl, alias, r.cfg.Templates[alias]); err != nil {
			return nil, err
		}
	}

	return tmpl, nil
}

func (r *renderer) addTemplateRef(tmpl *template.Template, alias string, ref DatasourceConfig) error {
	if localPath, isDir, ok := localFilePath(ref.URL); ok && isDir {
		files, err := listFiles(localPath)
		if err != nil {
			return err
		}
		for _, filePath := range files {
			rel, err := filepath.Rel(localPath, filePath)
			if err != nil {
				return err
			}
			content, err := os.ReadFile(filePath)
			if err != nil {
				return err
			}
			templateName := path.Join(alias, filepath.ToSlash(rel))
			if _, err := tmpl.New(templateName).Parse(string(content)); err != nil {
				return fmt.Errorf("parse template %s: %w", templateName, err)
			}
		}
		return nil
	}

	content, err := r.ds.loadTemplate(ref)
	if err != nil {
		return err
	}
	if _, err := tmpl.New(alias).Parse(content); err != nil {
		return fmt.Errorf("parse template %s: %w", alias, err)
	}
	return nil
}

func (r *renderer) outputPathFor(rel string, root any) (string, error) {
	if r.cfg.OutputMap == "" {
		return filepath.Join(r.cfg.OutputDir, filepath.FromSlash(rel)), nil
	}

	tmpl, err := r.buildTemplateSet("<outputMap>")
	if err != nil {
		return "", err
	}
	if _, err := tmpl.Parse(r.cfg.OutputMap); err != nil {
		return "", fmt.Errorf("renderTemplate: parse template <outputMap>: %w", err)
	}

	ctx := map[string]any{
		"in":  rel,
		"ctx": root,
	}
	if rootMap, ok := root.(map[string]any); ok {
		for key, value := range rootMap {
			if key == "in" || key == "ctx" {
				continue
			}
			ctx[key] = value
		}
	}

	var builder strings.Builder
	if err := tmpl.ExecuteTemplate(&builder, "<outputMap>", ctx); err != nil {
		return "", fmt.Errorf("renderTemplate: failed to render template <outputMap>: %w", err)
	}
	return strings.TrimSpace(builder.String()), nil
}

func (r *renderer) readInput(name string) ([]byte, error) {
	if name == "-" {
		return r.ds.stdin()
	}
	return os.ReadFile(name)
}

func normalizeMissingKey(mode string) string {
	if mode == "default" {
		return "invalid"
	}
	return mode
}

func openOutput(name string, mode, dirMode fs.FileMode) (io.WriteCloser, error) {
	if name == "-" {
		return nopWriteCloser{Writer: os.Stdout}, nil
	}
	if dirMode == 0 {
		dirMode = 0o755
	}
	parent := filepath.Dir(name)
	if parent != "." && parent != "" {
		if err := os.MkdirAll(parent, dirMode); err != nil {
			return nil, err
		}
	}
	return os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, mode)
}

func copyFile(src, dst string, mode, dirMode fs.FileMode) error {
	body, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	writer, err := openOutput(dst, mode, dirMode)
	if err != nil {
		return err
	}
	defer writer.Close()
	_, err = writer.Write(body)
	return err
}

func parseFileMode(value string) (fs.FileMode, error) {
	parsed, err := strconv.ParseUint(value, 8, 32)
	if err != nil {
		return 0, fmt.Errorf("parse chmod %q: %w", value, err)
	}
	return fs.FileMode(parsed), nil
}

func inputName(input string) string {
	if input == "" {
		return "<arg>"
	}
	return input
}

func listFiles(root string) ([]string, error) {
	var files []string
	err := filepath.WalkDir(root, func(filePath string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			return nil
		}
		files = append(files, filePath)
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(files)
	return files, nil
}

