package gomplate

import (
	"bytes"
	"context"
	"encoding/csv"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	stdnet "net"
	"net/netip"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"sort"
	stdstrings "strings"
	"time"

	toml "github.com/pelletier/go-toml/v2"
	"go4.org/netipx"
	"gopkg.in/yaml.v3"
)

type envNamespace struct {
	Env map[string]string
}

type mathNamespace struct{}

type netNamespace struct {
	experimental bool
}

type dataNamespace struct{}

type convNamespace struct{}

type collNamespace struct{}

type stringsNamespace struct{}

type filepathNamespace struct{}

type fileNamespace struct{}

type parsedNumber struct {
	isFloat bool
	i       int64
	f       float64
}

func buildFuncMap(ds *datasourceManager, cfg *RuntimeConfig) map[string]any {
	mathNS := &mathNamespace{}
	netNS := &netNamespace{experimental: cfg.Experimental}
	dataNS := &dataNamespace{}
	convNS := &convNamespace{}
	collNS := &collNamespace{}
	stringsNS := &stringsNamespace{}
	filepathNS := &filepathNamespace{}
	fileNS := &fileNamespace{}

	funcs := map[string]any{
		"env": func() *envNamespace {
			return &envNamespace{Env: snapshotEnv()}
		},
		"getenv": getenv,

		"math": func() *mathNamespace { return mathNS },
		"add":  mathNS.Add,
		"sub":  mathNS.Sub,
		"mul":  mathNS.Mul,
		"div":  mathNS.Div,
		"pow":  mathNS.Pow,
		"rem":  mathNS.Rem,
		"seq":  mathNS.Seq,

		"net": func() *netNamespace { return netNS },

		"data": func() *dataNamespace { return dataNS },
		"json":         dataNS.JSON,
		"jsonArray":    dataNS.JSONArray,
		"yaml":         dataNS.YAML,
		"toml":         dataNS.TOML,
		"toJSON":       dataNS.ToJSON,
		"toJSONPretty": dataNS.ToJSONPretty,
		"toYAML":       dataNS.ToYAML,
		"toTOML":       dataNS.ToTOML,

		"conv": func() *convNamespace { return convNS },
		"join": convNS.Join,

		"coll": func() *collNamespace { return collNS },

		"strings": func() *stringsNamespace { return stringsNS },
		"filepath": func() *filepathNamespace {
			return filepathNS
		},
		"file": func() *fileNamespace { return fileNS },

		"dict":     dict,
		"default":  defaultFn,
		"required": requiredFn,

		"datasource": func(alias string, subpaths ...string) (any, error) {
			return ds.LoadParsed(alias, subpaths...)
		},
		"ds": func(alias string, subpaths ...string) (any, error) {
			return ds.LoadParsed(alias, subpaths...)
		},
		"include": func(alias string, subpaths ...string) (string, error) {
			return ds.Include(alias, subpaths...)
		},
		"datasourceExists":    ds.Exists,
		"datasourceReachable": ds.Reachable,
		"listDatasources":     ds.List,
		"defineDatasource": func(alias, target string) (string, error) {
			ds.DefineIfMissing(alias, DatasourceConfig{URL: target})
			return "", nil
		},
	}

	names := make([]string, 0, len(cfg.Plugins))
	for name := range cfg.Plugins {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		funcs[name] = makePluginFunc(cfg.Plugins[name], cfg.PluginTimeout)
	}

	return funcs
}

func snapshotEnv() map[string]string {
	env := map[string]string{}
	for _, item := range os.Environ() {
		key, value, ok := stdstrings.Cut(item, "=")
		if ok {
			env[key] = value
		}
	}
	return env
}

func getenv(key string, defaults ...string) string {
	if value, ok := os.LookupEnv(key); ok && value != "" {
		return value
	}
	if filePath, ok := os.LookupEnv(key + "_FILE"); ok && filePath != "" {
		if body, err := os.ReadFile(filePath); err == nil {
			return stdstrings.TrimRight(string(body), "\r\n")
		}
	}
	if len(defaults) > 0 {
		return defaults[0]
	}
	return ""
}

