func (m *mathNamespace) Add(nums ...any) (any, error) {
	if len(nums) == 0 {
		return int64(0), nil
	}
	var sumInt int64
	var sumFloat float64
	anyFloat := false
	for _, item := range nums {
		value, err := parseNumber(item)
		if err != nil {
			return nil, fmt.Errorf("expected number inputs: %w", err)
		}
		if value.isFloat {
			anyFloat = true
		}
		sumInt += value.i
		sumFloat += value.float64()
	}
	if anyFloat {
		return sumFloat, nil
	}
	return sumInt, nil
}

func (m *mathNamespace) Sub(a, b any) (any, error) {
	left, err := parseNumber(a)
	if err != nil {
		return nil, fmt.Errorf("expected number inputs: %w", err)
	}
	right, err := parseNumber(b)
	if err != nil {
		return nil, fmt.Errorf("expected number inputs: %w", err)
	}
	if left.isFloat || right.isFloat {
		return left.float64() - right.float64(), nil
	}
	return left.i - right.i, nil
}

func (m *mathNamespace) Mul(nums ...any) (any, error) {
	if len(nums) == 0 {
		return int64(1), nil
	}
	productInt := int64(1)
	productFloat := 1.0
	anyFloat := false
	for _, item := range nums {
		value, err := parseNumber(item)
		if err != nil {
			return nil, fmt.Errorf("expected number inputs: %w", err)
		}
		if value.isFloat {
			anyFloat = true
		}
		productInt *= value.i
		productFloat *= value.float64()
	}
	if anyFloat {
		return productFloat, nil
	}
	return productInt, nil
}

func (m *mathNamespace) Div(a, b any) (float64, error) {
	left, err := parseNumber(a)
	if err != nil {
		return 0, fmt.Errorf("expected number inputs: %w", err)
	}
	right, err := parseNumber(b)
	if err != nil {
		return 0, fmt.Errorf("expected number inputs: %w", err)
	}
	if right.float64() == 0 {
		return 0, errors.New("error: division by 0")
	}
	return left.float64() / right.float64(), nil
}

func (m *mathNamespace) Pow(a, b any) (any, error) {
	left, err := parseNumber(a)
	if err != nil {
		return nil, fmt.Errorf("expected number inputs: %w", err)
	}
	right, err := parseNumber(b)
	if err != nil {
		return nil, fmt.Errorf("expected number inputs: %w", err)
	}
	value := math.Pow(left.float64(), right.float64())
	if left.isFloat || right.isFloat {
		return value, nil
	}
	return int64(value), nil
}

func (m *mathNamespace) Rem(a, b any) (int64, error) {
	left, err := parseIntegerValue(a)
	if err != nil {
		return 0, fmt.Errorf("expected number inputs: %w", err)
	}
	right, err := parseIntegerValue(b)
	if err != nil {
		return 0, fmt.Errorf("expected number inputs: %w", err)
	}
	if right == 0 {
		return 0, errors.New("error: division by 0")
	}
	return left % right, nil
}

func (m *mathNamespace) Seq(args ...any) ([]int64, error) {
	var start int64 = 1
	var end int64
	var step int64 = 1

	switch len(args) {
	case 1:
		value, err := parseIntegerValue(args[0])
		if err != nil {
			return nil, err
		}
		end = value
	case 2:
		first, err := parseIntegerValue(args[0])
		if err != nil {
			return nil, err
		}
		second, err := parseIntegerValue(args[1])
		if err != nil {
			return nil, err
		}
		start = first
		end = second
	case 3:
		first, err := parseIntegerValue(args[0])
		if err != nil {
			return nil, err
		}
		second, err := parseIntegerValue(args[1])
		if err != nil {
			return nil, err
		}
		third, err := parseIntegerValue(args[2])
		if err != nil {
			return nil, err
		}
		start = first
		end = second
		step = third
	default:
		return nil, fmt.Errorf("expected 1-3 arguments")
	}

	if step == 0 {
		return nil, fmt.Errorf("step must not be 0")
	}
	if step < 0 {
		step = -step
	}

	direction := int64(1)
	if start > end {
		direction = -1
	}

	var values []int64
	for current := start; ; current += direction * step {
		if direction > 0 && current > end {
			break
		}
		if direction < 0 && current < end {
			break
		}
		values = append(values, current)
	}
	return values, nil
}

func (m *mathNamespace) Abs(input any) (any, error) {
	value, err := parseNumber(input)
	if err != nil {
		return nil, fmt.Errorf("n must be a number: %w", err)
