func (m *mathNamespace) Max(nums ...any) (any, error) {
	if len(nums) == 0 {
		return nil, fmt.Errorf("expected at least one number")
	}
	values := make([]parsedNumber, 0, len(nums))
	anyFloat := false
	for _, item := range nums {
		value, err := parseNumber(item)
		if err != nil {
			return nil, fmt.Errorf("expected number inputs: %w", err)
		}
		if value.isFloat {
			anyFloat = true
		}
		values = append(values, value)
	}
	if anyFloat {
		result := values[0].float64()
		for _, value := range values[1:] {
			result = math.Max(result, value.float64())
		}
		return result, nil
	}
	result := values[0].i
	for _, value := range values[1:] {
		if value.i > result {
			result = value.i
		}
	}
	return result, nil
}

func (m *mathNamespace) Min(nums ...any) (any, error) {
	if len(nums) == 0 {
		return nil, fmt.Errorf("expected at least one number")
	}
	values := make([]parsedNumber, 0, len(nums))
	anyFloat := false
	for _, item := range nums {
		value, err := parseNumber(item)
		if err != nil {
			return nil, fmt.Errorf("expected number inputs: %w", err)
		}
		if value.isFloat {
			anyFloat = true
		}
		values = append(values, value)
	}
	if anyFloat {
		result := values[0].float64()
		for _, value := range values[1:] {
			result = math.Min(result, value.float64())
		}
		return result, nil
	}
	result := values[0].i
	for _, value := range values[1:] {
		if value.i < result {
			result = value.i
		}
	}
	return result, nil
}

