func dict(args ...any) (map[string]any, error) {
	if len(args)%2 != 0 {
		return nil, fmt.Errorf("dict expects an even number of arguments")
	}
	result := map[string]any{}
	for index := 0; index < len(args); index += 2 {
		result[fmt.Sprint(args[index])] = args[index+1]
	}
	return result, nil
}

func defaultFn(defaultValue any, value any) any {
	if isEmpty(value) {
		return defaultValue
	}
	return value
}

func requiredFn(args ...any) (any, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("can not render template: a required value was not set")
	}

	message := "can not render template: a required value was not set"
	value := args[len(args)-1]
	if len(args) > 1 {
		message = fmt.Sprint(args[0])
	}
	if isEmpty(value) {
		return nil, errors.New(message)
	}
	return value, nil
}

func makePluginFunc(cfg PluginConfig, fallbackTimeout time.Duration) func(args ...any) (string, error) {
	timeout := cfg.Timeout
	if timeout <= 0 {
		timeout = fallbackTimeout
	}

	return func(args ...any) (string, error) {
		ctx, cancel := context.WithTimeout(context.Background(), timeout)
		defer cancel()

		cmdArgs := append([]string(nil), cfg.Args...)
		var stdin string

		if cfg.Pipe && len(args) > 0 {
			stdin = fmt.Sprint(args[len(args)-1])
			args = args[:len(args)-1]
		}
		for _, arg := range args {
			cmdArgs = append(cmdArgs, fmt.Sprint(arg))
		}

		command := exec.CommandContext(ctx, cfg.Cmd, cmdArgs...)
		if cfg.Pipe {
			command.Stdin = stdstrings.NewReader(stdin)
		}

		var stdout bytes.Buffer
		var stderr bytes.Buffer
		command.Stdout = &stdout
		command.Stderr = &stderr

		if err := command.Start(); err != nil {
			return "", fmt.Errorf("starting command: %w", err)
		}
		if err := command.Wait(); err != nil {
			if ctx.Err() == context.DeadlineExceeded {
				return "", fmt.Errorf("plugin timed out after %s", timeout)
			}
			if stderr.Len() > 0 {
				return "", fmt.Errorf("running command: %w: %s", err, stdstrings.TrimSpace(stderr.String()))
			}
			return "", fmt.Errorf("running command: %w", err)
		}
		return stdout.String(), nil
	}
}

func parseNumber(input any) (parsedNumber, error) {
	switch value := input.(type) {
	case int:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case int8:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case int16:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case int32:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case int64:
		return parsedNumber{i: value, f: float64(value)}, nil
	case uint:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case uint8:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case uint16:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case uint32:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case uint64:
		return parsedNumber{i: int64(value), f: float64(value)}, nil
	case float32:
		return parsedNumber{isFloat: true, i: int64(value), f: float64(value)}, nil
	case float64:
		return parsedNumber{isFloat: true, i: int64(value), f: value}, nil
	case string:
		return parseNumericString(value)
	default:
		return parsedNumber{}, fmt.Errorf("unexpected type %T", input)
	}
}

func parseNumericString(input string) (parsedNumber, error) {
	trimmed := stdstrings.TrimSpace(input)
	if isFloatLiteral(trimmed) {
		value, err := strconv.ParseFloat(trimmed, 64)
		if err != nil {
			return parsedNumber{}, fmt.Errorf("could not convert %q to float64: %w", input, err)
		}
		return parsedNumber{isFloat: true, i: int64(value), f: value}, nil
	}

	intValue, err := strconv.ParseInt(trimmed, 0, 64)
	if err == nil {
		return parsedNumber{i: intValue, f: float64(intValue)}, nil
	}

	floatValue, floatErr := strconv.ParseFloat(trimmed, 64)
	if floatErr == nil {
		return parsedNumber{isFloat: true, i: int64(floatValue), f: floatValue}, nil
	}
	return parsedNumber{}, fmt.Errorf("could not convert %q to int64: %w", input, floatErr)
}

func (n parsedNumber) float64() float64 {
	if n.isFloat {
		return n.f
	}
	return float64(n.i)
}

func isFloatLiteral(input string) bool {
	switch input {
	case "NaN", "+Inf", "Inf", "-Inf":
		return true
	}
	return stdstrings.ContainsAny(input, ".eE")
}

func parseIntegerValue(input any) (int64, error) {
	value, err := parseNumber(input)
	if err != nil {
		return 0, err
	}
	if value.isFloat {
		return int64(value.f), nil
	}
	return value.i, nil
}

func isEmpty(value any) bool {
	if value == nil {
		return true
	}
	switch v := value.(type) {
	case string:
		return v == ""
	case bool:
		return !v
	case int:
		return v == 0
	case int8:
		return v == 0
	case int16:
		return v == 0
	case int32:
		return v == 0
	case int64:
		return v == 0
	case uint:
		return v == 0
	case uint8:
		return v == 0
	case uint16:
		return v == 0
	case uint32:
		return v == 0
	case uint64:
		return v == 0
	case float32:
		return v == 0
	case float64:
		return v == 0
	}

	rv := reflect.ValueOf(value)
	switch rv.Kind() {
	case reflect.Array, reflect.Map, reflect.Slice, reflect.String:
		return rv.Len() == 0
	case reflect.Interface, reflect.Pointer:
		return rv.IsNil()
	}
	return false
}

func toInterfaceSlice(input any) ([]any, error) {
	rv := reflect.ValueOf(input)
	if !rv.IsValid() {
		return nil, nil
	}
	if rv.Kind() != reflect.Array && rv.Kind() != reflect.Slice {
		return nil, fmt.Errorf("expected slice input, got %T", input)
	}
	values := make([]any, 0, rv.Len())
	for index := 0; index < rv.Len(); index++ {
		values = append(values, rv.Index(index).Interface())
	}
	return values, nil
}

func toString(input any) string {
	switch value := input.(type) {
	case string:
		return value
	case []byte:
		return string(value)
	default:
		return fmt.Sprint(input)
	}
}

