func (d *DatasourceConfig) UnmarshalYAML(node *yaml.Node) error {
	if node.Kind == yaml.ScalarNode {
		d.URL = node.Value
		return nil
	}

	type raw DatasourceConfig
	var tmp raw
	if err := node.Decode(&tmp); err != nil {
		return err
	}
	*d = DatasourceConfig(tmp)
	return nil
}

type PluginConfig struct {
	Cmd     string        `yaml:"cmd"`
	Args    []string      `yaml:"args"`
	Pipe    bool          `yaml:"pipe"`
	Timeout time.Duration `yaml:"timeout"`
}

func (p *PluginConfig) UnmarshalYAML(node *yaml.Node) error {
	if node.Kind == yaml.ScalarNode {
		p.Cmd = node.Value
		return nil
	}

	type raw PluginConfig
	var tmp raw
	if err := node.Decode(&tmp); err != nil {
		return err
	}
	*p = PluginConfig(tmp)
	return nil
}

type FileConfig struct {
	Chmod             string                      `yaml:"chmod"`
	Context           map[string]DatasourceConfig `yaml:"context"`
	Datasources       map[string]DatasourceConfig `yaml:"datasources"`
	Excludes          []string                    `yaml:"excludes"`
	ExcludeProcessing []string                    `yaml:"excludeProcessing"`
	ExecPipe          bool                        `yaml:"execPipe"`
	Experimental      bool                        `yaml:"experimental"`
	In                string                      `yaml:"in"`
	InputDir          string                      `yaml:"inputDir"`
