package gomplate

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

type yamlParser struct {
	lines []string
}

func parseYAMLDocument(input string) (any, error) {
	parser := yamlParser{lines: strings.Split(strings.ReplaceAll(input, "\r\n", "\n"), "\n")}
	value, index, err := parser.parseBlock(0, 0)
	if err != nil {
		return nil, err
	}
	index = parser.skipIgnored(index)
	if index < len(parser.lines) {
		return nil, fmt.Errorf("unexpected trailing content")
	}
	if value == nil {
		return map[string]any{}, nil
	}
	return value, nil
}

func (p *yamlParser) parseBlock(index, indent int) (any, int, error) {
	index = p.skipIgnored(index)
	if index >= len(p.lines) {
		return nil, index, nil
	}
	lineIndent, text := p.line(index)
	if lineIndent < indent {
		return nil, index, nil
	}
	if strings.HasPrefix(strings.TrimSpace(text), "- ") {
		return p.parseSequence(index, indent)
	}
	return p.parseMap(index, indent)
}

func (p *yamlParser) parseMap(index, indent int) (map[string]any, int, error) {
	result := map[string]any{}
	for index < len(p.lines) {
		index = p.skipIgnored(index)
		if index >= len(p.lines) {
			break
		}
		lineIndent, raw := p.line(index)
		if lineIndent < indent {
			break
		}
		if lineIndent > indent {
			return nil, index, fmt.Errorf("unexpected indentation")
		}
		text := strings.TrimSpace(raw)
		if strings.HasPrefix(text, "- ") {
			break
		}
		key, rest, ok := splitKeyValue(text)
		if !ok {
			return nil, index, fmt.Errorf("invalid mapping line %q", text)
		}
		index++

		switch {
		case rest == "|":
			value, next := p.parseLiteral(index, indent+2)
			result[key] = value
			index = next
		case rest == "":
			child, next, err := p.parseBlock(index, indent+2)
			if err != nil {
				return nil, index, err
			}
			if child == nil {
				result[key] = ""
			} else {
				result[key] = child
			}
			index = next
		default:
			value, err := parseScalar(rest)
			if err != nil {
				return nil, index, err
			}
			result[key] = value
		}
	}
	return result, index, nil
}

func (p *yamlParser) parseSequence(index, indent int) ([]any, int, error) {
	var result []any
	for index < len(p.lines) {
		index = p.skipIgnored(index)
		if index >= len(p.lines) {
			break
		}
		lineIndent, raw := p.line(index)
		if lineIndent < indent {
			break
		}
		if lineIndent != indent {
			return nil, index, fmt.Errorf("unexpected indentation")
		}
		text := strings.TrimSpace(raw)
		if !strings.HasPrefix(text, "- ") {
			break
		}
		itemText := strings.TrimSpace(strings.TrimPrefix(text, "- "))
		index++

		switch {
		case itemText == "|":
			value, next := p.parseLiteral(index, indent+2)
			result = append(result, value)
			index = next
		case itemText == "":
			child, next, err := p.parseBlock(index, indent+2)
			if err != nil {
				return nil, index, err
			}
			result = append(result, child)
			index = next
		default:
			if key, rest, ok := splitKeyValue(itemText); ok {
				item := map[string]any{}
				if rest == "|" {
					value, next := p.parseLiteral(index, indent+2)
					item[key] = value
					index = next
				} else if rest == "" {
					child, next, err := p.parseBlock(index, indent+2)
					if err != nil {
						return nil, index, err
					}
					item[key] = child
					index = next
				} else {
					value, err := parseScalar(rest)
					if err != nil {
						return nil, index, err
					}
					item[key] = value
				}
				if index < len(p.lines) {
					nextIndent, nextRaw := p.line(index)
					if nextIndent == indent+2 && !strings.HasPrefix(strings.TrimSpace(nextRaw), "- ") {
						extra, next, err := p.parseMap(index, indent+2)
						if err != nil {
							return nil, index, err
						}
						for extraKey, extraValue := range extra {
							item[extraKey] = extraValue
						}
						index = next
					}
				}
				result = append(result, item)
				continue
			}
			value, err := parseScalar(itemText)
			if err != nil {
				return nil, index, err
			}
			result = append(result, value)
		}
	}
	return result, index, nil
}

func (p *yamlParser) parseLiteral(index, indent int) (string, int) {
	var lines []string
	for index < len(p.lines) {
		raw := p.lines[index]
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			lines = append(lines, "")
			index++
			continue
		}
		lineIndent, _ := p.line(index)
		if lineIndent < indent {
			break
		}
		if len(raw) >= indent {
			lines = append(lines, raw[indent:])
		} else {
			lines = append(lines, trimmed)
		}
		index++
	}
	if len(lines) == 0 {
		return "", index
	}
	return strings.Join(lines, "\n") + "\n", index
}

func (p *yamlParser) skipIgnored(index int) int {
	for index < len(p.lines) {
		trimmed := strings.TrimSpace(p.lines[index])
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			index++
			continue
		}
		break
	}
	return index
}

func (p *yamlParser) line(index int) (int, string) {
	raw := p.lines[index]
	indent := 0
	for indent < len(raw) && raw[indent] == ' ' {
		indent++
	}
	return indent, raw
}

func splitKeyValue(line string) (string, string, bool) {
	inSingle := false
	inDouble := false
	for index, r := range line {
		switch r {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case ':':
			if !inSingle && !inDouble {
				key := strings.TrimSpace(line[:index])
				value := strings.TrimSpace(line[index+1:])
				return key, value, true
			}
		}
	}
	return "", "", false
}

func parseScalar(input string) (any, error) {
	input = strings.TrimSpace(input)
	if input == "" {
		return "", nil
	}
	if strings.HasPrefix(input, "\"") && strings.HasSuffix(input, "\"") && len(input) >= 2 {
		return strconv.Unquote(input)
	}
	if strings.HasPrefix(input, "'") && strings.HasSuffix(input, "'") && len(input) >= 2 {
		return input[1 : len(input)-1], nil
	}
	if strings.HasPrefix(input, "[") && strings.HasSuffix(input, "]") {
		return parseFlowList(input[1 : len(input)-1])
	}
	switch input {
	case "true":
		return true, nil
	case "false":
		return false, nil
	case "null":
		return nil, nil
	}
	if value, err := strconv.ParseInt(input, 0, 64); err == nil {
		return value, nil
	}
	if value, err := strconv.ParseFloat(input, 64); err == nil && strings.ContainsAny(input, ".eE") {
		return value, nil
	}
	return input, nil
}

func parseFlowList(input string) ([]any, error) {
	var items []any
	var current strings.Builder
	inSingle := false
	inDouble := false
	depth := 0
	flush := func() error {
		item := strings.TrimSpace(current.String())
		current.Reset()
		if item == "" {
			return nil
		}
		value, err := parseScalar(item)
		if err != nil {
			return err
		}
		items = append(items, value)
		return nil
	}

	for _, r := range input {
		switch r {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '[':
			if !inSingle && !inDouble {
				depth++
			}
		case ']':
			if !inSingle && !inDouble && depth > 0 {
				depth--
			}
		case ',':
			if !inSingle && !inDouble && depth == 0 {
				if err := flush(); err != nil {
					return nil, err
				}
				continue
			}
		}
		current.WriteRune(r)
	}
	if err := flush(); err != nil {
		return nil, err
	}
	return items, nil
}

func marshalYAMLDocument(value any) (string, error) {
	var builder strings.Builder
	if err := writeYAMLValue(&builder, value, 0, false); err != nil {
		return "", err
	}
	return builder.String(), nil
}

func writeYAMLValue(builder *strings.Builder, value any, indent int, listItem bool) error {
	switch typed := value.(type) {
	case map[string]any:
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			v := typed[key]
			prefix := strings.Repeat(" ", indent)
			if isScalar(v) {
				builder.WriteString(prefix)
				builder.WriteString(key)
				builder.WriteString(": ")
				builder.WriteString(formatYAMLScalar(v))
				builder.WriteString("\n")
				continue
			}
			if text, ok := v.(string); ok && strings.Contains(text, "\n") {
				builder.WriteString(prefix)
				builder.WriteString(key)
				builder.WriteString(": |\n")
				for _, line := range strings.Split(strings.TrimSuffix(text, "\n"), "\n") {
					builder.WriteString(prefix)
					builder.WriteString("  ")
					builder.WriteString(line)
					builder.WriteString("\n")
				}
				continue
			}
			builder.WriteString(prefix)
			builder.WriteString(key)
			builder.WriteString(":\n")
			if err := writeYAMLValue(builder, v, indent+2, false); err != nil {
				return err
			}
		}
	case []any:
		for _, item := range typed {
			prefix := strings.Repeat(" ", indent)
			if isScalar(item) {
				builder.WriteString(prefix)
				builder.WriteString("- ")
				builder.WriteString(formatYAMLScalar(item))
				builder.WriteString("\n")
				continue
			}
			builder.WriteString(prefix)
			builder.WriteString("-\n")
			if err := writeYAMLValue(builder, item, indent+2, true); err != nil {
				return err
			}
		}
	default:
		prefix := strings.Repeat(" ", indent)
		if listItem {
			builder.WriteString(prefix)
			builder.WriteString(formatYAMLScalar(typed))
			builder.WriteString("\n")
		} else {
			builder.WriteString(prefix)
			builder.WriteString(formatYAMLScalar(typed))
			builder.WriteString("\n")
		}
	}
	return nil
}

func isScalar(value any) bool {
	switch value.(type) {
	case nil, string, bool, int, int64, float64, float32:
		return true
	default:
		return false
	}
}

func formatYAMLScalar(value any) string {
	switch typed := value.(type) {
	case nil:
		return "null"
	case string:
		if typed == "" {
			return "''"
		}
		if strings.ContainsAny(typed, ":\n#[]{}") || strings.HasPrefix(typed, " ") || strings.HasSuffix(typed, " ") {
			return strconv.Quote(typed)
		}
		return typed
	case bool:
		if typed {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprint(typed)
	}
}

func parseTOMLDocument(input string) (map[string]any, error) {
	root := map[string]any{}
	current := root

	for _, raw := range strings.Split(strings.ReplaceAll(input, "\r\n", "\n"), "\n") {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section := strings.TrimSpace(line[1 : len(line)-1])
			current = ensureTOMLSection(root, strings.Split(section, "."))
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("invalid TOML line %q", line)
		}
		parsed, err := parseScalar(strings.TrimSpace(value))
		if err != nil {
			return nil, err
		}
		current[strings.TrimSpace(key)] = parsed
	}

	return root, nil
}

func ensureTOMLSection(root map[string]any, parts []string) map[string]any {
	current := root
	for _, part := range parts {
		next, ok := current[part].(map[string]any)
		if !ok {
			next = map[string]any{}
			current[part] = next
		}
		current = next
	}
	return current
}

func marshalTOMLDocument(value any) (string, error) {
	root, ok := value.(map[string]any)
	if !ok {
		return "", fmt.Errorf("TOML root must be a map")
	}
	var builder strings.Builder
	writeTOMLMap(&builder, root, nil)
	return builder.String(), nil
}

func writeTOMLMap(builder *strings.Builder, value map[string]any, prefix []string) {
	keys := make([]string, 0, len(value))
	for key := range value {
		keys = append(keys, key)
	}
	sort.Strings(keys)

	for _, key := range keys {
		if _, ok := value[key].(map[string]any); ok {
			continue
		}
		builder.WriteString(key)
		builder.WriteString(" = ")
		builder.WriteString(formatTOMLScalar(value[key]))
		builder.WriteString("\n")
	}

	for _, key := range keys {
		child, ok := value[key].(map[string]any)
		if !ok {
			continue
		}
		if builder.Len() > 0 && !strings.HasSuffix(builder.String(), "\n\n") {
			builder.WriteString("\n")
		}
		section := append(append([]string(nil), prefix...), key)
		builder.WriteString("[")
		builder.WriteString(strings.Join(section, "."))
		builder.WriteString("]\n")
		writeTOMLMap(builder, child, section)
	}
}

func formatTOMLScalar(value any) string {
	switch typed := value.(type) {
	case string:
		return strconv.Quote(typed)
	case []any:
		parts := make([]string, 0, len(typed))
		for _, item := range typed {
			parts = append(parts, formatTOMLScalar(item))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case bool:
		if typed {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprint(typed)
	}
}

func asMap(value any) map[string]any {
	if value == nil {
		return nil
	}
	if mapped, ok := value.(map[string]any); ok {
		return mapped
	}
	return nil
}

func asString(value any) string {
	switch typed := value.(type) {
	case nil:
		return ""
	case string:
		return typed
	case int64:
		return strconv.FormatInt(typed, 10)
	case float64:
		return strconv.FormatFloat(typed, 'f', -1, 64)
	case bool:
		if typed {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprint(typed)
	}
}

func asBool(value any) bool {
	switch typed := value.(type) {
	case bool:
		return typed
	case string:
		parsed, _ := strconv.ParseBool(typed)
		return parsed
	default:
		return false
	}
}

func asDuration(value any) time.Duration {
	duration, _ := time.ParseDuration(asString(value))
	return duration
}

func asStringSlice(value any) []string {
	switch typed := value.(type) {
	case []string:
		return append([]string(nil), typed...)
	case []any:
		result := make([]string, 0, len(typed))
		for _, item := range typed {
			result = append(result, asString(item))
		}
		return result
	default:
		return nil
	}
}

